// Team designer (#2193, interactive #2199) — the persona-relationship graph, mounted as the Team tab of
// the Planner workspace. Navigation is IN the graph (#2742): the TOP level is a Teams overview (every
// team a clickable card, the rail lists the teams); clicking a card enters that team's position graph;
// a breadcrumb (Teams › team) climbs back up. The old header org-switcher dropdown is gone. The team is
// AI-configured now (#2750) and READ-ONLY since #2382: the user inspects, and no longer creates,
// edits or deletes teams/positions/relationships by hand — no create buttons, no click-to-connect
// palette, no inspector CRUD, no right-click delete. `bsc teams` / `bsc persona` are what write. Per team: toolbar (breadcrumb ·
// auto-organize/fit/zoom) · left rail (positions by department, or teams at the top level) · canvas
// (pan/zoom/node-drag) · inspector (position identity / relationship). Driven by the real org/persona/
// skill stores; pure model + geometry live in lib/*.
// The pan/zoom shell is the shared GraphCanvas template + useGraphViewport (#2208, epic #2197 slice 2).
import departmentsEmbedded from "@data/teams/departments.json";
import { useEffect, useMemo, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { IconBox } from "@/shared/ui/data/IconBox";
import { GraphCanvas, ZoomControls } from "@/shared/ui/layouts/GraphCanvas";
import { GraphRail } from "@/shared/ui/layouts/GraphRail";
import { RailRow } from "@/shared/ui/layouts/RailRow";
import { RailSection } from "@/shared/ui/layouts/RailSection";
import { SearchField } from "@/shared/ui/controls/SearchField";
import { useRailSections } from "@/shared/hooks/useRailSections";
import { useGraphViewport } from "@/shared/ui/layouts/useGraphViewport";
import { TeamsCanvas, type Selection } from "@/features/teams/TeamsCanvas";
import { GraphLegend, type LegendNode } from "@/shared/ui/layouts/GraphLegend";
import { TeamsOverview } from "@/features/teams/TeamsOverview";
import { usePageTabs } from "@/shared/hooks/usePageTabs";
import { Screen } from "@/shared/ui/layouts/Screen";
import { TeamsInspector } from "@/features/teams/TeamsInspector";
import { ArchitectTerminal } from "@/features/teams/ArchitectTerminal";
import { useDragResize } from "@/shared/hooks/useDragResize";
import { useDockEntrance } from "@/shared/hooks/useDockEntrance";
import { useCrumbEntity } from "@/shared/hooks/useCrumbEntity";
import { RELATIONSHIP_ARCHETYPES, type Position } from "@/features/teams/lib/team";
import { resolveAllInstalledMcp, BUILTIN_MCP_SERVERS } from "@/features/mcp";
import { autoLayout, nodeBox, contentBounds, CANVAS_W, CANVAS_H, type Box as GBox } from "@/features/teams/lib/orgLayout";
import { teamsBounds } from "@/features/teams/lib/teamsLayout";
import { detectPools, collapseOrg, poolLayoutSizes, applyPoolLayout } from "@/features/teams/lib/orgPools";
import { positionDisplay, hueColor } from "@/features/teams/lib/orgView";
import { overlayFile } from "@/shared/lib/core/configOverrides";

/** Department display order in the left rail (positionDisplay assigns each a dept) — from
 *  `@data/teams/departments.json` (#2419, beside the teams vocabulary); config-dir-overlaid (#2047). */
const DEPT_ORDER: string[] = overlayFile("teams/departments.json", departmentsEmbedded);

export function TeamsPanel() {
  const orgs = useAppStore((s) => s.teams);
  const personas = useAppStore((s) => s.personas);
  // The skills library. A skill is injectable agent CONTEXT, so it belongs beside the agents that
  // carry it rather than on a rail destination of its own — that is the whole move.
  const skills = useAppStore((s) => s.skills);
  // MCP servers are agent capability too, so they are read here beside the agents that use them —
  // the same argument that put skills on this page. `resolveAllInstalledMcp` PREPENDS the built-in
  // servers: the store holds only user-installed ones, and rendering just those would show an empty
  // section while three servers are in fact reaching every session.
  const mcpServers = useAppStore((s) => s.mcpServers);
  const allMcp = useMemo(() => resolveAllInstalledMcp(mcpServers), [mcpServers]);
  const updateOrg = useAppStore((s) => s.updateOrg);
  const updatePosition = useAppStore((s) => s.updatePosition);
  const setOrgZoom = useAppStore((s) => s.setTeamsZoom);

  // The ENTERED team (#2742) — null = the top-level Teams overview, where the graph shows every team as
  // a card and the user drills IN by clicking one (no header dropdown). `atTeams` also catches a stale
  // id whose team was deleted, so we never render a missing team.

  // ── THE TEAM IS THE AXIS (`define-the-axis-for-teams-data-and-sounds`) ───────────────────────────
  //
  // Every other graph's axis is a technology, and Teams deliberately does NOT follow. The first
  // proposal was to tab by HARNESS (claude-code vs bsc-agent) and the maintainer rejected it: a tab bar
  // splitting agents by runtime "suggests one llm can't work with another", which is false and is the
  // wrong claim to build into the chrome. It also had no data behind it — a persona carries id, name and
  // role, and nothing else.
  //
  // The TEAM is the axis that is already there. A team IS the cooperation unit: `bsc teams list` returns
  // disjoint teams, and this page already modelled exactly this drill (#2742) — an overview of cards,
  // click one to enter, a breadcrumb back. Lifting that into the tab bar is the same move the other
  // graphs made, and it carries no implication about technology at all: a team may hold personas on any
  // model or harness, which is the flexibility that was asked for.
  //
  // The overview stays as the LEADING tab rather than a second mechanism beside the bar. Keeping both a
  // tab strip and a separate way to pick a team would be two selectors for one concept — the thing that
  // makes them drift — so the breadcrumb's Teams crumb now selects this tab instead of bypassing it.
  // The Studio Network renders here EXACTLY as it is stored (#debug-nodes-hang-off-the-session-that-filed-them).
  // It used to get the standing `debugger` node overlaid; that node is gone, and the live request
  // sessions that replaced it are a GLANCE concern — this is the team DESIGNER, where a transient
  // runtime node would be draggable against a team it is not part of.
  /** The overview's tab id. Not a team id, and `teams` is not a legal team id, so they cannot collide. */
  const ALL_TEAMS = "teams";
  const teamTabs = useMemo(
    () => [
      { id: ALL_TEAMS, label: "All teams", hint: "every team, as cards" },
      ...orgs.map((o) => ({ id: o.id, label: o.name, hint: `${o.name} — ${o.positions.length} positions` })),
    ],
    [orgs],
  );
  // UNCONTROLLED (`navigation-vocabulary-follows-the-new-page-structure`): the entered team is READ
  // from `activePageTab["teams"]` rather than held in local state, so `bsc navigate page <teamId>`
  // reaches it and the choice survives a restart.
  //
  // Tear-off is not wired: `studioDetached` looks for the architect's `sectionId` ("teams"), not a team
  // id, so a detached team tab would be a window the architect dock does not follow.
  const { tabs, activeId, select: selectTab, reorder } = usePageTabs("teams", teamTabs);
  // A tab id that is not a real team — the overview, or a team since deleted — means "no team entered",
  // so the overview renders. usePageTabs heals a stale id to the front tab, which IS the overview.
  const orgId = activeId === ALL_TEAMS ? null : activeId;
  const org = orgId ? orgs.find((o) => o.id === orgId) : undefined;
  // Name the entered team in the titlebar crumb (#3041) — "" on the teams overview.
  useCrumbEntity("teams", org?.name ?? "");
  const savedZoom = useAppStore((s) => s.teamsZoom[orgId ?? ""]);
  // Open with nothing selected (the empty sentinel — inspector empty, no dimming; see onBackgroundClick).
  const [sel, setSel] = useState<Selection>({ type: "node", id: "" });

  // The nodes of the collapsed graph — computed on demand for framing. fit + the saved-zoom restore
  // center on THESE, not the fixed 1120×800 canvas, so the graph opens centered instead of parked high
  // / clipped at the top (#2673). Mirrors `view` below. (The pool-member drill was dropped, #2750.)
  const framedPositions = (): Position[] => {
    if (!org) return [];
    return collapseOrg(org, detectPools(org, personas)).org.positions;
  };
  // What the viewport fits/centers on — the team cards at the top level (#2742), else the framed
  // positions of the entered team (mirrors `atTeams`/`view` below, read fresh each fit).
  const framedBounds = (): GBox | null =>
    !org ? teamsBounds(orgs.length + 1) : contentBounds(framedPositions());

  const vp = useGraphViewport(
    { w: CANVAS_W, h: CANVAS_H },
    { min: 0.4, max: 1.5, fitPad: 20, maxFitScale: 1.5, contentBounds: framedBounds },
  );
  const scale = vp.view.scale;

  // The docked team-architect session's height (#2755) — a row-resize handle above it; `invert`
  // because the terminal sits AFTER the handle, so dragging up grows it. Mirrors the Design Studio's
  // terminal dock (DesignsWorkbench).
  const term = useDragResize({ initial: 340, min: 140, max: 560, axis: "y", invert: true });
  useDockEntrance(term.setSize, 340); // grow the dock up into place on mount (#2905)

  // The always-on architect session, docked below the graph on BOTH graph levels (#2759). Passing the
  // SAME element to the overview AND the entered-team GraphCanvas — which React reconciles as ONE
  // instance (the GraphCanvas sits at index 0 of each return's fragment) — keeps the terminal (and its
  // PTY) mounted across the overview↔team switch, so the session is never torn down when you navigate
  // levels. GraphCanvas gives the dock a `flex: none` slot; we own its height + a `.resize-y` handle.
  const dock = (
    <Box style={{ display: "flex", flexDirection: "column", minHeight: 0 }}>
      <Box className="resize-y" {...term.handleProps} title="Drag to resize" />
      <ArchitectTerminal height={term.size} />
    </Box>
  );

  // The Skills rail section, rendered at BOTH graph levels (the overview AND inside a team): a skill
  // is global, so which team you happen to be looking at does not change the library. Selecting one
  // does NOT move the canvas — the graph keeps showing the team while the inspector shows the skill.
  const skillsRail = (open: boolean, onToggle: () => void) => {
    const rows = skills.filter((sk) => railMatch(sk.name));
    if (!rows.length) return null;
    return (
      <RailSection label="Skills" count={rows.length} open={open} onToggle={onToggle}>
        {rows.map((sk) => {
          const on = sel.type === "skill" && sel.id === sk.id;
          const carriers = personas.filter((p) => p.skills.includes(sk.id)).length;
          return (
            <RailRow key={sk.id} active={on} onClick={() => setSel({ type: "skill", id: sk.id })}
              leading={<IconBox size={20} radius={6} fontSize={11} color="var(--accent)" background="var(--bg-soft)">✦</IconBox>}
              trailing={<Text as="span" mono size={9} tone="dim">{carriers}</Text>}>
              {sk.name}
            </RailRow>
          );
        })}
      </RailSection>
    );
  };

  // The MCP rail section, rendered at BOTH graph levels for the same reason the Skills one is: a
  // server is global capability, so which team is on screen does not change the set. A BUILT-IN is
  // marked, because "always available to every session" and "someone installed this" are different
  // facts and only one of them is a choice anybody made.
  const mcpRail = (open: boolean, onToggle: () => void) => {
    const rows = allMcp.filter((m) => railMatch(m.name));
    if (!rows.length) return null;
    return (
      <RailSection label="MCP" count={rows.length} open={open} onToggle={onToggle}>
        {rows.map((m) => {
          const on = sel.type === "mcp" && sel.id === m.id;
          const builtin = BUILTIN_MCP_SERVERS.some((b) => b.id === m.id);
          return (
            <RailRow key={m.id} active={on} onClick={() => setSel({ type: "mcp", id: m.id })}
              leading={<IconBox size={20} radius={6} fontSize={11} color="var(--info, var(--accent))" background="var(--bg-soft)">⧉</IconBox>}
              trailing={<Text as="span" mono size={9} tone="dim">{builtin ? "built-in" : m.projects.length === 0 ? "global" : String(m.projects.length)}</Text>}>
              {m.name}
            </RailRow>
          );
        })}
      </RailSection>
    );
  };

  // Rail search + section-collapse (#2797) — one query filters the visible rail (teams at the top
  // level, positions inside a team); dept sections default open. Shared across both graph levels.
  const [query, setQuery] = useState("");
  const railSections = useRailSections();
  const q = query.trim().toLowerCase();
  const railMatch = (name: string) => !q || name.toLowerCase().includes(q);

  // Restore this org's saved zoom (or fit) when the org changes. zoomToCentered (NOT zoomTo) re-centers
  // the world at the saved scale — zoomTo anchors about the viewport center starting from the fresh
  // mount's {0,0,1} origin, which leaves the world hanging off the bottom of the viewport (#2545).
  useEffect(() => {
    if (savedZoom) vp.zoomToCentered(savedZoom);
    else vp.fit();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [orgId]);

  // Persist zoom, debounced so a wheel-zoom gesture doesn't spam the store.
  const saveTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
  useEffect(() => {
    clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(() => setOrgZoom(orgId ?? "", scale), 400);
    return () => clearTimeout(saveTimer.current);
  }, [scale, orgId, setOrgZoom]);

  // Enter a team's position graph (a card / rail click); `toTeams` climbs back to the overview.
  // Entering or leaving a team clears a GRAPH selection (a node id means nothing in another team) but
  // keeps a SKILL one: the library is global, so a skill you were reading stays readable across the
  // navigation that only ever moved the canvas.
  // A function DECLARATION, not a const: the tab wiring above calls it, and `const` would be in the
  // temporal dead zone there. Hoisting is the point rather than an accident of style.
  function clearGraphSel() {
    setSel((cur) => (cur.type === "skill" ? cur : { type: "node", id: "" }));
  }
  // Entering a team and climbing back are both TAB selections — one selector, not two.
  const enterTeam = (id: string) => { selectTab(id); clearGraphSel(); };
  const toTeams = () => { selectTab(ALL_TEAMS); clearGraphSel(); };

  // No teams yet is NOT an empty-state page (#3033): the `!org` overview below still renders the graph +
  // rail + the architect terminal with zero team cards, so the graph is always present (and the terminal,
  // which is where the AI configures teams, #2750, stays reachable) — never hidden behind a blocking card.

  // ── TOP LEVEL (#2742): the Teams overview — every team is a card you click to enter; the left rail
  // lists the teams. This replaced the header org-switcher dropdown. `!org` also covers a stale/deleted
  // id, and narrows `org` to a real Team for the per-team code below.
  /** The tab strip, shared by both levels so the bar never disappears mid-navigation. */
  const screenProps = { tabs, active: activeId, onSelect: selectTab, onReorder: reorder, className: "teams-workspace" };

  if (!org) {
    return (
      <Screen {...screenProps}>
      <>
      <GraphCanvas
        vp={vp}
        world={{ w: CANVAS_W, h: CANVAS_H }}
        grid
        railResizable railWidth={260} railMin={200} railMax={420}
        dock={dock}
        toolbar={
          <>
            <Row gap={9} align="center">
              <IconBox size={22} radius={6} fontSize={12} background="var(--bg-soft)" border="1px solid var(--border)" color="var(--accent)">◆</IconBox>
              <Text as="span" weight={600} size={14}>Teams</Text>
              <Text as="span" mono size={10.5} tone="dim">{orgs.length} team{orgs.length === 1 ? "" : "s"} · click one to open</Text>
            </Row>
            <Box style={{ flex: 1 }} />
            <Button variant="ghost" onClick={vp.fit}>Fit</Button>
            <ZoomControls vp={vp} />
          </>
        }
        rail={
          <GraphRail
            bodyPad="8px 8px 20px"
            tools={<SearchField value={query} onChange={setQuery} placeholder="Search teams…" aria-label="Search teams" style={{ width: "100%" }} />}
          >
            {orgs.filter((o) => railMatch(o.name)).map((o) => (
              <RailRow key={o.id} onClick={() => enterTeam(o.id)}
                leading={<IconBox size={20} radius={6} fontSize={11} color="var(--accent)" background="var(--bg-soft)">◆</IconBox>}
                trailing={<Text as="span" mono size={9} tone="dim">{o.positions.length}</Text>}>
                {o.name}
              </RailRow>
            ))}
            {skillsRail(railSections.isOpen("Skills"), () => railSections.toggle("Skills"))}
                {mcpRail(railSections.isOpen("MCP"), () => railSections.toggle("MCP"))}
          </GraphRail>
        }
      >
        <Box className="graph-drill-anim" style={{ position: "absolute", inset: 0 }}>
          <TeamsOverview teams={orgs} personas={personas} onEnter={enterTeam} />
        </Box>
      </GraphCanvas>
      </>
      </Screen>
    );
  }

  // Selecting a node just focuses it — the click-to-connect relationship builder was removed (#2750;
  // the AI configures teams, the user only inspects/deletes).
  const onSelectNode = (nodeId: string) => setSel({ type: "node", id: nodeId });

  // Pools (#2199): homogeneous swarms of a `pooled` persona collapse to one stacked card. The canvas
  // shows the COLLAPSED parent graph (the pool-member drill was dropped, #2750 — a swarm is already
  // fully represented by its ×N stacked card).
  const pools = detectPools(org, personas);
  const collapsed = collapseOrg(org, pools);
  const view = collapsed;

  // Auto-organize lays out the graph being RENDERED (#2451): the COLLAPSED org, so the pool node
  // participates (with its stacked-card footprint) and lands ON a hierarchy row; the result writes back
  // through applyPoolLayout — non-pooled nodes directly, each pool's members translated as a cluster so
  // their centroid (where the stack renders) is the pool's laid-out spot (#2439).
  const autoOrganize = () => {
    const layout = autoLayout(collapsed.org, poolLayoutSizes(pools));
    updateOrg(org.id, { positions: applyPoolLayout(org, pools, layout) });
  };

  // Left rail: positions grouped by department, in canonical order.
  const byDept = new Map<string, typeof org.positions>();
  for (const p of org.positions) {
    const dept = positionDisplay(p, personas).dept;
    (byDept.get(dept) ?? byDept.set(dept, []).get(dept)!).push(p);
  }
  const depts = [...byDept.keys()].sort((a, b) => {
    const ia = DEPT_ORDER.indexOf(a), ib = DEPT_ORDER.indexOf(b);
    return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
  });

  // Nothing is selected while `sel.id` is the empty sentinel — the inspector column is HIDDEN then
  // (don't render an empty panel), and it appears only once a node/edge is actually selected.
  const hasSel = sel.id !== "";

  // The on-graph legend (#2909) — the position KINDS + the relationship archetypes actually present in
  // this team, keyed off the same hue/style the canvas draws with, so it reads relevant to the team.
  const legendNodes: LegendNode[] = [];
  const kinds = new Set(org.positions.map((p) => p.kind));
  if (kinds.has("agent")) legendNodes.push({ label: "Agent", color: "var(--accent)" });
  if (kinds.has("resource")) legendNodes.push({ label: "Resource", color: hueColor(340) });
  if (kinds.has("external")) legendNodes.push({ label: "External", color: "var(--fg-muted)" });
  const presentArch = new Set(org.relationships.map((r) => r.archetype));
  const legend = (
    <GraphLegend
      sections={[
        { label: "Positions", nodes: legendNodes },
        { label: "Relationships", edges: RELATIONSHIP_ARCHETYPES.filter((a) => presentArch.has(a.id)).map((a) => ({ label: a.label, color: hueColor(a.hue), dashed: a.style !== "solid" })) },
      ]}
    />
  );

  return (
    <Screen {...screenProps}>
    <>
    <GraphCanvas
      vp={vp}
      world={{ w: CANVAS_W, h: CANVAS_H }}
      overlays={legend}
      grid
      railResizable railWidth={260} railMin={200} railMax={420}
      inspectorResizable inspectorWidth={344} inspectorMin={280} inspectorMax={560}
      // The always-on team-architect session (#2755/#2759) — the SHARED `dock` element, present on BOTH
      // graph levels so it persists across the overview↔team switch. The Teams graph stays the read-only
      // viewer; the architect creates/refines teams + personas via `bsc teams` / `bsc persona`.
      dock={dock}
      // Click the empty canvas → clear the selection (the empty sentinel; inspector empties, no dimming).
      onBackgroundClick={() => setSel({ type: "node", id: "" })}
      toolbar={
        <>
          {/* Breadcrumb (#2742) — Teams › ‹team›; the Teams crumb climbs back to the overview (replaces
              the header org-switcher dropdown, which is gone; teams are entered from the graph now).
              The pool crumb was dropped with the pool-member drill (#2750). */}
          <Row gap={7} align="center">
            <IconBox size={22} radius={6} fontSize={12} background="var(--bg-soft)" border="1px solid var(--border)" color="var(--accent)">◆</IconBox>
            <Button variant="ghost" onClick={toTeams}>Teams</Button>
            <Text as="span" tone="dim">›</Text>
            <Text as="span" weight={600} size={14}>{org.name}</Text>
            <Text as="span" mono size={10.5} tone="dim" style={{ marginLeft: 2 }}>{org.positions.length} positions · {pools.length} pool{pools.length === 1 ? "" : "s"}</Text>
          </Row>
          <Box style={{ flex: 1 }} />
          <Button variant="ghost" onClick={autoOrganize}>⤢ Auto organize</Button>
          <Button variant="ghost" onClick={vp.fit}>Fit</Button>
          <ZoomControls vp={vp} />
        </>
      }
      rail={
        <GraphRail
          bodyPad="8px 8px 20px"
          tools={<SearchField value={query} onChange={setQuery} placeholder="Search positions…" aria-label="Search positions" style={{ width: "100%" }} />}
        >
          {depts.map((dept) => {
            const rows = byDept.get(dept)!
              .map((p) => ({ p, d: positionDisplay(p, personas) }))
              .filter(({ d }) => railMatch(d.name));
            if (!rows.length) return null;
            return (
              <RailSection key={dept} label={dept} count={rows.length}
                open={railSections.isOpen(dept)} onToggle={() => railSections.toggle(dept)}>
                {rows.map(({ p, d }) => {
                  const on = sel.type === "node" && sel.id === p.nodeId;
                  return (
                    <RailRow key={p.nodeId} active={on} onClick={() => onSelectNode(p.nodeId)}
                      leading={<IconBox size={20} radius={6} fontSize={11} color="var(--accent)" background="var(--bg-soft)">{d.glyph}</IconBox>}
                      trailing={d.role ? <Text as="span" mono size={9} tone="dim" style={{ textTransform: "uppercase" }}>{d.role}</Text> : undefined}>
                      {d.name}
                    </RailRow>
                  );
                })}
              </RailSection>
            );
          })}
          {skillsRail(railSections.isOpen("Skills"), () => railSections.toggle("Skills"))}
                {mcpRail(railSections.isOpen("MCP"), () => railSections.toggle("MCP"))}
        </GraphRail>
      }
      inspector={hasSel ? (
        <TeamsInspector
          org={org} orgs={orgs} personas={personas} skills={skills} mcpServers={allMcp} sel={sel}
          onSelectNode={(id) => setSel({ type: "node", id })}
          onSelectSkill={(id) => setSel({ type: "skill", id })}
          onSelectPersona={(personaId) => {
            // A skill lists the personas that carry it; clicking one goes to a POSITION that embodies
            // it, because a position is what the graph can show. A persona with no position in this
            // team has nowhere to land, so the selection is left alone rather than cleared — silently
            // deselecting would read as a broken click.
            const pos = org.positions.find((p) => p.personaId === personaId);
            if (pos) setSel({ type: "node", id: pos.nodeId });
          }}
        />
      ) : undefined}
    >
      {/* keyed to the team so entering/leaving replays the shared transition (graphCanvas.css, #2418) */}
      <Box key={org.id} className="graph-drill-anim" style={{ position: "absolute", inset: 0 }}>
        <TeamsCanvas
          org={view.org} personas={personas} sel={sel} scale={scale} connecting={false}
          dragMoved={vp.dragMoved} poolInfo={view.poolInfo}
          onSelectNode={onSelectNode} onSelectEdge={(id) => setSel({ type: "edge", id })}
          onMoveNode={(nodeId, x, y) => updatePosition(org.id, nodeId, { x, y })}
          onMovePool={(poolNodeId, dx, dy) => {
            // The pool node is synthetic (rendered at its members' centroid) — commit a stack drag by
            // shifting EVERY member by the delta, so the centroid lands at the drop point and the
            // drill-in keeps its relative arrangement (#2439). nodeBox supplies the same default
            // position the canvas rendered, so members without a stored x/y shift from where they SHOW.
            const members = collapsed.poolInfo[poolNodeId]?.memberNodeIds ?? [];
            for (const m of members) {
              const pos = org.positions.find((p) => p.nodeId === m);
              if (!pos) continue;
              const b = nodeBox(pos);
              updatePosition(org.id, m, { x: b.x + dx, y: b.y + dy });
            }
          }}
        />
      </Box>
    </GraphCanvas>
    </>
    </Screen>
  );
}

